Yes you are right. They are complete different.
RM2k (or maybe 2k3?) uses percentage, but MV just adds the rgb value directly.
MV:
newcolor = oldcolor + tintcolor
2K:
if percentage<100%
newcolor = oldcolor * percentage
if percentage>100%
newcolor = oldcolor + (255 - oldcolor) * (percentage-100%)
Edit*
This should simulate the RM2k styled screen tone.
JavaScript:
ToneFilter.prototype.adjustTone = function(r, g, b) {
    r = (r || 0).clamp(-255, 255) / 255;
    g = (g || 0).clamp(-255, 255) / 255;
    b = (b || 0).clamp(-255, 255) / 255;


    var R=1,G=1,B=1;
    //rm 2k tint
    R = r<0?(1+r):(1-r);
    r = r<0?0:r;
    G = g<0?(1+g):(1-g);
    g = g<0?0:g;
    B = b<0?(1+b):(1-b);
    b = b<0?0:b;


    if (r !== 0 || g !== 0 || b !== 0||R !== 1 || G !== 1 || B !== 1) {
        var matrix = [
            R, 0, 0, r,  0,
            0, G, 0, g, 0,
            0, 0, B, b, 0,
            0, 0, 0, 1, 0
        ];


        this._loadMatrix(matrix, true);
    }
};

